<?php get_header(); the_post(); ?><article <?php post_class( 'gmr-news-single' ); ?>><header class="gmr-news-single__head"><div class="gmr-wrap"><span class="gmr-kicker">Noticias · <?php echo esc_html( get_the_date( 'j F, Y' ) ); ?></span><div class="gmr-news-single__categories"><?php echo wp_kses_post( get_the_category_list( ' · ' ) ); ?></div><h1><?php the_title(); ?></h1><?php if ( has_excerpt() ) : ?><p><?php echo esc_html( get_the_excerpt() ); ?></p><?php endif; ?></div></header><?php if ( has_post_thumbnail() ) : ?><figure class="gmr-news-single__cover gmr-wrap"><?php the_post_thumbnail( 'full' ); ?><?php if ( $caption = get_the_post_thumbnail_caption() ) : ?><figcaption><?php echo esc_html( $caption ); ?></figcaption><?php endif; ?></figure><?php endif; ?><div class="gmr-news-single__body gmr-wrap"><div class="gmr-news-single__aside"><span>Galería Mayarí Rojas</span><time datetime="<?php echo esc_attr( get_the_date( DATE_W3C ) ); ?>"><?php echo esc_html( get_the_date( 'Y' ) ); ?></time></div><div class="gmr-news-single__content"><?php the_content(); wp_link_pages(); ?></div></div><footer class="gmr-news-single__footer gmr-wrap"><a class="gmr-news-link" href="<?php echo esc_url( gmr_theme_page_url( 'noticias' ) ); ?>">← Ver todas las noticias</a></footer></article><?php get_footer(); ?>
